import os
import subprocess

# Get current working directory
cwd = os.getcwd()
print(f"Current Directory: {cwd}\n")

# List contents
result = subprocess.run(['ls', '-la'], capture_output=True, text=True)
print("Directory listing:")
print(result.stdout)

# Check if items are files or directories
for item in ['project', 'data', 'notes.txt', 'config.yaml']:
    if os.path.exists(item):
        if os.path.isfile(item):
            size = os.path.getsize(item)
            print(f"\n{item} is a FILE - {size} bytes")
            if size < 10000:  # Only read small files
                try:
                    with open(item, 'r') as f:
                        content = f.read()
                        print(f"Content:\n{content[:500]}")
                except:
                    print("(binary or unreadable)")
        elif os.path.isdir(item):
            print(f"\n{item} is a DIRECTORY")
            for root, dirs, files in os.walk(item):
                print(f"  {root}/")
                for f in files:
                    fpath = os.path.join(root, f)
                    try:
                        fsize = os.path.getsize(fpath)
                        print(f"    - {f} ({fsize} bytes)")
                    except:
                        print(f"    - {f} (unreadable)")
